/** Stacking order, lowest first. */
export const layer = { sticky: 3, popover: 5, fab: 30, chat: 31, search: 40, menu: 45, dialog: 50, toast: 60 } as const;

/**
 * Durations in ms. Every animation stops under prefers-reduced-motion. The design system sets no
 * motion tokens; these are Blinq Scribe's own.
 */
export const motion = { fast: 80, normal: 150, slow: 300, level: 900, pulse: 1200, shimmer: 1400 } as const;

export const tokens = { color, colorDark, font, type, text, leading, tracking, weight, space, size, radius, shadow, shadowDark, layer, motion } as const;
export type Tokens = typeof tokens;
export type ColorToken = keyof typeof color;

const kebab = (s: string) => s.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`);
const px = (n: number) => `${n}px`;

/** The light colors alone, for `.theme-light`: a surface that stays light inside a dark page. */
export function lightColorVariables(): [string, string][] {
  return Object.entries(color).map(([k, v]): [string, string] => [`--color-${kebab(k)}`, v]);
}

/** The tokens that change in dark mode, named like their light twins; applied under `data-theme="dark"`. */
export function darkCssVariables(): [string, string][] {
  return [
    ...Object.entries(colorDark).map(([k, v]): [string, string] => [`--color-${kebab(k)}`, v]),
    ...Object.entries(shadowDark).map(([k, v]): [string, string] => [`--shadow-${kebab(k)}`, v]),
  ];
}

/**
 * Every token except the shadows and the type as a CSS custom property, named the way Tailwind 4's
 * theme reads them (--color-*, --radius-*, --font-*, --font-weight-*), plus our own namespaces for
 * the rest. These go in Tailwind's @theme. Type reaches the screens only as the role utilities
 * (see typeUtilities), so no --text-* or --tracking-* variable is emitted.
 */
export function themeVariables(): [string, string][] {
  return [
    ...Object.entries(color).map(([k, v]): [string, string] => [`--color-${kebab(k)}`, v]),
    ...Object.entries(font).map(([k, v]): [string, string] => [`--font-${kebab(k)}`, v]),
    ...Object.entries(weight).map(([k, v]): [string, string] => [`--font-weight-${kebab(k)}`, String(v)]),
    ...Object.entries(space).map(([k, v]): [string, string] => [`--space-${k}`, px(v)]),
    ...Object.entries(size).map(([k, v]): [string, string] => [`--size-${kebab(k)}`, px(v)]),
    ...Object.entries(radius).map(([k, v]): [string, string] => [`--radius-${kebab(k)}`, px(v)]),
    ...Object.entries(layer).map(([k, v]): [string, string] => [`--layer-${kebab(k)}`, String(v)]),
    ...Object.entries(motion).map(([k, v]): [string, string] => [`--duration-${kebab(k)}`, `${v}ms`]),
  ];
}

/**
 * Each type role as the declarations of its utility, by class name (`text-body-strong`), then the
 * numeral utility. `font-num`: the text font with tabular figures, so a Number keeps the size and weight
 * of its line and lines up in a column.
 */
export function typeUtilities(): [string, [string, string][]][] {
  const roles = Object.entries(type).map(([k, r]): [string, [string, string][]] => {
    const decls: [string, string][] = [
      ["font-size", px(r.size)],
      ["line-height", px(r.line)],
      ["font-weight", String(r.weight)],
    ];
    if ("tracking" in r) decls.push(["letter-spacing", r.tracking]);
    if ("uppercase" in r && r.uppercase) decls.push(["text-transform", "uppercase"]);
    if ("color" in r) decls.push(["color", `var(--color-${kebab(r.color)})`]);
    return [`text-${kebab(k)}`, decls];
  });
  return [
    ...roles,
    [
      "font-num",
      [
        ["font-family", "var(--font-sans)"],
        ["font-variant-numeric", "tabular-nums"],
      ],
    ],
  ];
}

/**
 * The shadows as plain custom properties. Kept out of @theme: Tailwind 4 copies a theme shadow's
 * value into its utility, so the dark override would never reach `shadow-card`. The utilities read
 * the variable instead (see renderTheme).
 */
export function shadowVariables(): [string, string][] {
  return Object.entries(shadow).map(([k, v]): [string, string] => [`--shadow-${kebab(k)}`, v]);
}

/** Every token as a CSS custom property. */
export function cssVariables(): [string, string][] {
  return [...themeVariables(), ...shadowVariables()];
}
